// Builds assets/diagram/visual.js for the Android app: the desktop ```visual
// renderer (src/lib/visual) + DOMPurify as one offline IIFE.
//   node scripts/build-visual-bundle.mjs           write the bundle
//   node scripts/build-visual-bundle.mjs --check   fail when the committed bundle is stale
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { build } from 'esbuild'

const here = dirname(fileURLToPath(import.meta.url))
const appDir = resolve(here, '..')

export const BUNDLE_PATH = resolve(appDir, '../../../assets/diagram/visual.js')

export async function buildVisualBundle() {
  const result = await build({
    banner: {
      js: '/* Neovarch visual renderer, generated by desktop/apps/desktop/scripts/build-visual-bundle.mjs (do not edit). Includes DOMPurify (Apache-2.0 OR MPL-2.0), see VISUAL_THIRD_PARTY.txt */'
    },
    bundle: true,
    entryPoints: [resolve(appDir, 'src/lib/visual/android-entry.ts')],
    format: 'iife',
    legalComments: 'none',
    minify: true,
    target: ['chrome80'],
    write: false
  })

  return result.outputFiles[0].text
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const text = await buildVisualBundle()

  if (process.argv.includes('--check')) {
    if (readFileSync(BUNDLE_PATH, 'utf8') !== text) {
      console.error('assets/diagram/visual.js is stale: run node scripts/build-visual-bundle.mjs')
      process.exit(1)
    }

    console.log('visual.js up to date')
  } else {
    writeFileSync(BUNDLE_PATH, text)
    console.log(`wrote ${BUNDLE_PATH} (${text.length} bytes)`)
  }
}
